package daemon

import (
	"encoding/json"

	"github.com/blerglab/blerg-ai/runner/internal/protocol"
)

// observePlan translates the installed Codex 0.162.1 turn/plan/updated
// notification. Its schema is generated by `codex app-server generate-ts`:
// threadId, turnId, explanation, plan:[{step,status}]. Native plans have no
// active form, so this adapter never invents one or infers steps from text.
//
// epoch is stamped when the native reader receives the event. A plan queued
// during turn/start may be applied after its response binds the accepted turn;
// an idle/prior-turn event cannot become the next turn's plan later.
func (a *codexApp) observePlan(raw json.RawMessage, epoch uint64) {
	if len(raw) > protocol.MaxPlanUpdatedBytes || epoch == 0 || a.ctx == nil || a.ctx.Err() != nil {
		return
	}
	var native struct {
		ThreadID string `json:"threadId"`
		TurnID   string `json:"turnId"`
		Plan     []struct {
			Step   string `json:"step"`
			Status string `json:"status"`
		} `json:"plan"`
	}
	if json.Unmarshal(raw, &native) != nil || native.Plan == nil || len(native.Plan) > protocol.MaxPlanItems {
		return
	}
	payload := protocol.PlanUpdatedPayload{Items: make([]protocol.PlanItem, 0, len(native.Plan))}
	for _, item := range native.Plan {
		status := item.Status
		switch status {
		case "inProgress":
			status = "in_progress"
		case "pending", "completed":
		default:
			return
		}
		payload.Items = append(payload.Items, protocol.PlanItem{Text: item.Step, Status: status})
	}
	clean, valid := protocol.SanitizePlanUpdated(payload)
	if !valid {
		return
	}
	a.d.mu.Lock()
	current := a.d.app == a && a.d.threadID != "" && native.ThreadID == a.d.threadID && a.d.activeTurn && !a.d.codexToolsRestricted()
	a.d.mu.Unlock()
	if !current {
		return
	}
	a.mu.Lock()
	current = a.planEpoch == epoch && a.turn != "" && native.TurnID == a.turn
	a.mu.Unlock()
	if !current || a.ctx.Err() != nil {
		return
	}
	select {
	case <-a.done:
		return
	default:
	}
	a.d.emit(protocol.PlanUpdatedKind, clean)
}
